CREATE TEMPORARY VIEW exchange_rate AS
    select  grass_region
            ,grass_date
            ,exchange_rate
    from    mp_order.dim_exchange_rate__reg_s0_live
    where   1 = 1
      and   grass_region in ('VN', 'TW', 'TH', 'PH', 'SG', 'MY', 'ID') -- 'KH', 'MM', 'LA'
      and   grass_date = ${local_date}
;
