CREATE TEMPORARY VIEW homecircle AS
select  grass_region
        ,grass_date
        ,module
        ,user_id
        ,sum(order_1d) as order_cnt
        ,sum(gmv_usd_1d) as gmv_usd
from    (
    -- DP+DP Local Service orders
    select  t1.grass_region
            ,t1.grass_date
            ,'Home Circle' as module
            ,t1.user_id
            ,t1.order_1d
            ,t1.total_amount/t2.exchange_rate as gmv_usd_1d
    from    (
        select  grass_region
                ,date(grass_date) as grass_date
                ,cast(user_id as bigint) as user_id
                ,count(distinct order_id) as order_1d
                ,sum(total_amount)*0.00001 as total_amount
        from    digitalpurchase.traffic_dwd_dp_order_by_traffic_entrance_di_v2
        where   1 = 1
          and   grass_region in ('VN', 'TW', 'TH', 'PH', 'SG', 'MY', 'ID') -- 'KH', 'MM', 'LA'
          and   date(grass_date) = ${local_date}
          and   is_gross_order = 1
          and   platform = 1
          and   is_bi_excluded = 0
          and   replace(replace(get_json_object(create_event_data,'$.dp_from_source'), 'buyagain', ''),' ', '') in ('1', '1_ls_circle', '1_lottery')
        -- https://confluence.shopee.io/pages/viewpage.action?pageId=1036577772
        group by 1, 2, 3
    ) t1
    left join exchange_rate t2
    on      t1.grass_region = t2.grass_region
      and   t1.grass_date = t2.grass_date
    union all
    -- Shopee Food orders
    select  t1.grass_region
            ,t1.grass_date
            ,'Home Circle' as module
            ,t1.user_id
            ,t1.order_1d
            ,t1.total_amount/t2.exchange_rate as gmv_usd_1d
    from    (
        select  'ID' as grass_region
                ,date(dt) as grass_date
                ,buyer_id as user_id
                ,count(distinct order_id) as order_1d
                ,sum(total_amount*0.00001) as total_amount
        from    shopeefood.shopeefood_mart_dwd_id_traffic_external_direct_order_attribute_di
        where   1 = 1
          and   date(dt) = ${local_date}
          and   target_type = 'home_circle'
        group by 1, 2, 3
        union all
        select  'TH' as grass_region
                ,date(dt) as grass_date
                ,buyer_id as user_id
                ,count(distinct order_id) as order_1d
                ,sum(total_amount*0.00001) as total_amount
        from    shopeefood.shopeefood_mart_dwd_th_traffic_external_direct_order_attribute_di
        where   1 = 1
          and   date(dt) = ${local_date}
          and   target_type = 'home_circle'
        group by 1, 2, 3
        union all
        select  'MY' as grass_region
                ,date(dt) as grass_date
                ,buyer_id as user_id
                ,count(distinct order_id) as order_1d
                ,sum(total_amount*0.00001) as total_amount
        from    shopeefood.shopeefood_mart_dwd_my_traffic_external_direct_order_attribute_di
        where   1 = 1
          and   date(dt) = ${local_date}
          and   target_type = 'home_circle'
        group by 1, 2, 3
        union all
        select  p1.grass_region
                ,p1.grass_date
                ,p2.user_id
                ,p1.order_1d
                ,p1.total_amount
        from    (
            select  'VN' as grass_region
                    ,date(dt) as grass_date
                    ,buyer_id as now_uid
                    ,count(distinct order_id) as order_1d
                    ,sum(total_amount*0.00001) as total_amount
            from    shopeefood.shopeefood_mart_dwd_vn_traffic_external_direct_order_attribute_di
            where   1 = 1
              and   date(dt) = ${local_date}
              and   target_type = 'home_circle'
            group by 1, 2, 3
        ) p1
        left join (
            select  now_uid
                    ,shopee_uid as user_id
                    ,dt as grass_date
            from    shopeefood.shopeefood_mart_cdm_dim_vn_buyer_now_shopee_mapping_da
            where   1 = 1
              and   dt = ${local_date}
        ) p2
        on      p1.grass_date = p2.grass_date
          and   p1.now_uid = p2.now_uid
    ) t1
    left join exchange_rate t2
    on      t1.grass_region = t2.grass_region
      and   t1.grass_date = t2.grass_date
) temp
group by 1, 2, 3, 4
union all
select  grass_region
        ,grass_date
        ,'Home Circle' as module
        ,user_id
        ,sum(place_order_cnt) as order_mp
        ,sum(place_order_gmv_usd) as gmv_mp
from    mp_campaign.dwd_eventid_orderid_atc_place_banner_di__reg_s0_live
where   1 = 1
  and   grass_region in ('VN', 'TW', 'TH', 'PH', 'SG', 'MY', 'ID') -- 'KH', 'MM', 'LA'
  and   grass_date = ${local_date}
  and   tz_type = 'local'
  and   banner_type_display_name in ('Home Square')
group by 1, 2, 3, 4
;
