CREATE TEMPORARY VIEW order_merged AS
select
grass_region
,grass_date
,module
,user_id
,order_cnt
,gmv_usd
,'order' as operation
from (
        -- homecircle
        select  grass_region
                ,grass_date
                ,module
                ,user_id
                ,order_cnt
                ,gmv_usd
                from homecircle
        union all
        --banner_skynny
        select  grass_region
                ,grass_date
                ,module
                ,user_id
                ,order_cnt
                ,gmv_usd
                from banner_skynny
        union all
        -- dp loc
        select  grass_region
                ,grass_date
                ,module
                ,user_id
                ,order_cnt
                ,gmv_usd
                from dp_local
        union all
        select  grass_region
                ,grass_date
                ,module
                ,user_id
                ,order_cnt
                ,gmv_usd
                from shopee_food
);
--sql_divide_splitter--
CREATE TEMPORARY VIEW imp_click_merged AS
select  user_id
        ,case   when target_type = 'banner' then 'Banner'
                when target_type = 'skinny_banner' then  'Skinny Banner'
                when target_type = 'home_circle' then  'Home Circle'
         end as module
        ,operation
        ,grass_region
        ,local_date
        ,sum(operation_cnt) as operation_cnt
from    srdi_mart.dwd_sr_data_warehouse_platform
where   grass_region in ('VN', 'TW', 'TH', 'PH', 'SG', 'MY', 'ID') -- 'KH', 'MM', 'LA'
  and   local_date = ${local_date}
  and   operation in ('impression', 'click')
  and   page_type = 'home'
  and   page_section is null
  and   target_type in ('banner', 'skinny_banner','home_circle')
  and   user_id > 0
group by 1, 2,3,4,5
;

--sql_divide_splitter--
INSERT OVERWRITE TABLE ${schema}.dwm_sr_data_warehouse_homepage_other_user
PARTITION (grass_region, local_date, operation)
select
    user_id
    ,module
    ,operation_cnt
    ,null as gmv_usd

    ,grass_region
    ,local_date
    ,operation
from imp_click_merged
union all
select
    user_id
    ,module
    ,order_cnt as operation_cnt
    ,gmv_usd

    ,grass_region
    ,grass_date as local_date
    ,operation
from order_merged

